def clean(df):
    df = df.copy()
    # Clean Price: strip $ and convert text numbers to numeric
    if 'Price' in df.columns:
        df['Price'] = df['Price'].astype(str).str.replace(r'[\$,]', '', regex=True).str.strip()
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    # Ensure Quantity numeric
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    # Normalize Region label variants (south/east -> South/East)
    if 'Region' in df.columns:
        df['Region'] = df['Region'].astype(str).str.strip().str.title()
    # Normalize Category whitespace
    if 'Category' in df.columns:
        df['Category'] = df['Category'].astype(str).str.strip()
    # Filter invalid Quantity (min 1, positive whole number)
    if 'Quantity' in df.columns:
        df = df[df['Quantity'] >= 1]
    # Filter invalid Price (min 0)
    if 'Price' in df.columns:
        df = df[df['Price'] >= 0]
    # Keep only allowed Categories
    allowed_cat = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
    if 'Category' in df.columns:
        df = df[df['Category'].isin(allowed_cat)]
    # Drop rows missing keys needed for question
    df = df.dropna(subset=['Category', 'Price'])
    return df

def answer(df):
    # average unit price per Category
    if df.empty or 'Category' not in df.columns or 'Price' not in df.columns:
        return {}
    g = df.groupby('Category')['Price'].mean()
    result = {}
    for k, v in g.items():
        if pd.isna(k):
            continue
        result[str(k)] = float(v)
    return result
